const fetch = require('cross-fetch');
const { ElectronBlocker } = require('@cliqz/adblocker-electron');

let mainWindow;
let blockedCount = 0;
let blocker;

async function setupAdBlocker(ses) {
  try {
    blocker = await ElectronBlocker.fromPrebuiltAdsAndTracking(fetch);
    blocker.enableBlockingInSession(ses);

    blocker.on('request-blocked', (request) => {
      blockedCount++;
      if (mainWindow && !mainWindow.isDestroyed()) {
        mainWindow.webContents.send('shield-update', {
          blockedCount,
          url: request.url
        });
      }
    });

    console.log('Ad & Tracker blocker initialized successfully with EasyList / EasyPrivacy.');
  } catch (err) {
    console.error('Failed to initialize ad blocker:', err);
  }
}

function setupPrivacyHeaders(ses) {
  // Enforce Global Privacy Control (GPC) and Do Not Track (DNT)
  ses.webRequest.onBeforeSendHeaders((details, callback) => {
