      try {
        const refUrl = new URL(details.requestHeaders['Referer']);
        const destUrl = new URL(details.url);
        if (refUrl.origin !== destUrl.origin) {
          details.requestHeaders['Referer'] = refUrl.origin + '/';
        }
      } catch (e) {
        delete details.requestHeaders['Referer'];
      }
    }

    callback({ cancel: false, requestHeaders: details.requestHeaders });
  });
}

