"* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  user-select: none;
}

body {
  background-color: #0b0f19;
  color: #f1f5f9;
  height: 100vh;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

/* Header & Tabs */
.app-header {
  height: 42px;
  background-color: #0f172a;
  display: flex;
  align-items: center;
  padding-left: 8px;
  border-bottom: 1px solid #1e293b;
  position: relative;
  -webkit-app-region: drag;
}

.header-drag-region {
  flex: 1;
  height: 100%;
}

.tabs-container {
  display: flex;
  align-items: center;
  gap: 4px;
  height: 100%;
  max-width: calc(100vw - 180px);
  overflow-x: auto;
  -webkit-app-region: no-drag;
}

.tab {
  height: 32px;
  min-width: 140px;
  max-width: 220px;
  background: #1e293b;
  border-radius: 8px 8px 0 0;
  display: flex;
  align-items: center;
  padding: 0 10px;
  gap: 8px;
  cursor: pointer;
  font-size: 12px;
  color: #94a3b8;
  transition: all 0.15s ease;
  border-top: 2px solid transparent;
}

.tab:hover {
  background: #334155;
  color: #f8fafc;
}

.tab.active {
  background: #1e293b;
  color: #38bdf8;
  border-top: 2px solid #38bdf8;
  font-weight: 500;
}

.tab-title {
  flex: 1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.tab-close {
  width: 18px;
  height: 18px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  color: #64748b;
  transition: all 0.1s;
}

.tab-close:hover {
  background: #475569;
  color: #f1f5f9;
}

.add-tab-btn {
  -webkit-app-region: no-drag;
  margin-left: 6px;
  font-size: 18px;
  font-weight: 300;
  color: #94a3b8;
}

/* Nav Bar */
.nav-bar {
  height: 48px;
  background-color: #1e293b;
  display: flex;
  align-items: center;
  padding: 0 12px;
  gap: 10px;
  border-bottom: 1px solid #334155;
  z-index: 10;
}\
