  const blocker = await ElectronBlocker.fromPrebuiltAdsAndTracking(fetch);
  blocker.enableBlockingInSession(ses);

  blocker.on('request-blocked', (req) => {
    console.log('[BLOCKER BLOCKED]', req.url);
  });

  const win = new BrowserWindow({
    show: false,
    webPreferences: {
      session: ses
    }
  });

  win.webContents.on('did-start-loading', () => console.log('Started loading'));
  win.webContents.on('did-finish-load', () => console.log('Finished load successfully!'));
  win.webContents.on('did-fail-load', (e, code, desc, url) => {
    console.log('Failed load:', code, desc, url);
  });
  win.webContents.on('console-message', (e, level, msg, line, src) => {
    console.log('[PAGE CONSOLE]', msg);
  });

  console.log('Navigating to YouTube...');
  try {
    await win.loadURL('https://www.youtube.com/?gl=IN');
    console.log('Page Title:', await win.getTitle());
  } catch (err) {
    console.error('loadURL caught error:', err);
